-- mesh.lua
-- Generated by eilmer-mesher. Edit the .emesh.json project, not this file.
--   lmr prep-grids -j mesh.lua      registers the grids for a simulation
--   lmr custom-script -j mesh.lua   writes preview/blk-NNNN.vtk for the GUI
if config then config.dimensions = 2 end

-- points
p000 = Vector3:new{x=0.01, y=0.02}
p001 = Vector3:new{x=0.01, y=0.01}
p002 = Vector3:new{x=0.0, y=0.0}
p003 = Vector3:new{x=0.01, y=0.0}
p004 = Vector3:new{x=-0.003, y=0.0}
p005 = Vector3:new{x=-0.003, y=0.01}
p006 = Vector3:new{x=0.003, y=0.015}

-- paths
path_north = Line:new{p0=p000, p1=p001}
path_east = Arc:new{p0=p002, p1=p001, centre=p003}
path_south = Line:new{p0=p004, p1=p002}
path_west = Bezier:new{points={p004, p005, p006, p000}}

-- blocks
blocks = {}
-- block blk0
surf_blk0 = CoonsPatch:new{north=path_north, east=path_east, south=path_south, west=path_west}
grid_blk0 = StructuredGrid:new{psurface=surf_blk0, niv=61, njv=81, label="blk0"}
blocks[#blocks+1] = {grid=grid_blk0, tag="blk0", fsTag="initial", bcTags={north="outflow", west="inflow"}}

if registerFluidGrid then
   -- lmr prep-grids
   local ids = {}
   for i, b in ipairs(blocks) do
      ids[i] = registerFluidGrid{grid=b.grid, tag=b.tag, fsTag=b.fsTag, bcTags=b.bcTags}
   end
   -- Blocks are joined only across block split lines; a solid curve between
   -- two blocks stays a wall on both sides.
   -- (no connections)
else
   -- lmr custom-script: preview output for the GUI
   os.execute("mkdir -p preview")
   for i, b in ipairs(blocks) do
      b.grid:write_to_vtk_file(string.format("preview/blk-%04d.vtk", i-1))
   end
end
